## Objective (minimize)
W_travel * total_travel + W_tard * total_tardiness + W_maxtard * max_tardiness
+ W_wait * total_waiting + W_extra * total_extra + W_idle * max_idle
+ W_pref * total_prefmiss + W_opt * skipped_optional + W_lunch * missed_lunch
"""
with open(os.path.join(SUB, "model.md"), "w") as f:
    f.write(model_md)

model.free()"}
